 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A horizontal 5-bar is a header; extend each color immediately below
    # its left end across the width of the bar.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and g[r][c] == 5:
                c += 1
            end = c
            if end - start >= 2 and r + 1 < h:
                for rr in range(r + 1, h):
                    color = g[rr][start]
                    if color == 0 or color == 5:
                        break
                    for cc in range(start, end):
                        g[rr][cc] = color

    # A vertical 5-bar is a left edge; repeat the nonzero row-pattern
    # immediately to its right upward through the bar's extent.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            top = r
            while r < h and g[r][c] == 5:
                r += 1
            bottom = r - 1
            # Find the contiguous pattern block adjoining the bottom edge.
            pbottom = bottom
            while pbottom >= top:
                if any(g[pbottom][cc] != 0 for cc in range(c + 1, w)):
                    break
                pbottom -= 1
            if pbottom < top:
                continue
            ptop = pbottom
            while ptop > top and any(g[ptop - 1][cc] != 0 for cc in range(c + 1, w)):
                ptop -= 1
            pattern = [g[rr][c + 1:] for rr in range(ptop, pbottom + 1)]
            period = len(pattern)
            for rr in range(top, ptop):
                g[rr][c + 1:] = pattern[(rr - ptop) % period]
    return g
